namespace GodTreeXOwais.Runtime; public sealed record AgentRequest(string Mission,string NodeId,string NodeName,string Workspace,IReadOnlyDictionary<string,string> Context); public sealed record AgentResponse(bool Success,string Summary,IReadOnlyList<string> Artifacts,string? Error=null); public interface IAgentProvider{string Id{get;} Task<AgentResponse> Execute(AgentRequest request,CancellationToken ct);} public sealed class LocalPlanningAgent:IAgentProvider{public string Id=>"local-planner";public async Task<AgentResponse> Execute(AgentRequest r,CancellationToken ct){var d=Path.Combine(r.Workspace,".godtree-generated");Directory.CreateDirectory(d);var f=Path.Combine(d,$"{r.NodeId}.md");await File.WriteAllTextAsync(f,$"# {r.NodeName}\n\nMission: {r.Mission}\n",ct);return new(true,$"{r.NodeName} materialized.",new[]{f});}}